type Phase = "idle" | "editing" | "saving" | "saved";

export const useDraftPhase = () => {
  const [phase, setPhase] = useState<Phase>("idle");
  const markTyping = () => {
    if (phase !== "saving") setPhase("editing");
  };
  const markSending = () => {
    if (phase === "editing") setPhase("saving");
  };
  const markFinished = () => {
    setPhase(phase === "saving" ? "saved" : "idle");
  };
  return { phase, markTyping, markSending, markFinished };
};

