export const watcher = { current: null as IntersectionObserver | null };

export const useSeen = (target: Element | null): boolean => {
  const [seen, setSeen] = useState(false);
  useEffect(() => {
    if (target === null) return;
    watcher.current = new IntersectionObserver(([entry]) => {
      setSeen(entry?.isIntersecting ?? false);
    });
    watcher.current.observe(target);
  }, [target]);
  return seen;
